1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Tetris</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  [hidden] { display: none !important; }
10	  body {
11	    margin: 0;
12	    min-height: 100vh;
13	    display: flex;
14	    align-items: center;
15	    justify-content: center;
16	    background: #14161c;
17	    color: #e8e8ec;
18	    font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
19	  }
20	  .game { display: flex; gap: 24px; align-items: flex-start; padding: 16px; }
21	  .board {
22	    display: grid;
23	    grid-template-columns: repeat(10, 28px);
24	    grid-template-rows: repeat(20, 28px);
25	    gap: 1px;
26	    padding: 1px;
27	    background: #2a2d36;
28	    border: 2px solid #3a3e4a;
29	  }
30	  .cell { width: 28px; height: 28px; background: #0d0e12; }
31	  .cell[data-ghost="true"] { box-shadow: inset 0 0 0 2px rgba(232, 232, 236, 0.45); }
32	  .paused { font-size: 14px; color: #f2d024; }
33	  .side { display: flex; flex-direction: column; gap: 16px; min-width: 140px; }
34	  .panel { background: #1d2028; border: 1px solid #2f333d; padding: 10px 12px; }
35	  .label { font-size: 11px; text-transform: uppercase; letter-spacing: 0.08em; color: #8a8f9c; }
36	  .value { font-size: 22px; font-weight: 600; margin-top: 2px; }
37	  .next-list { display: flex; flex-direction: column; gap: 10px; margin-top: 8px; }
38	  .next-item[data-piece], .hold-item[data-piece] { background: transparent !important; }
39	  .hold-item { margin-top: 8px; }
40	  .preview {
41	    display: grid;
42	    grid-template-columns: repeat(4, 16px);
43	    grid-template-rows: repeat(2, 16px);
44	    gap: 1px;
45	  }
46	  .preview .mini { width: 16px; height: 16px; background: transparent; }
47	  .status { font-size: 14px; color: #ff8a8a; min-height: 18px; }
48	  button {
49	    font: inherit;
50	    background: #2f333d;
51	    color: #e8e8ec;
52	    border: 1px solid #454a57;
53	    padding: 6px 10px;
54	    cursor: pointer;
55	  }
56	  button:hover { background: #3a3e4a; }
57	  .help { font-size: 12px; color: #8a8f9c; line-height: 1.6; }
58	
59	  /* Piece colours, shared by the board and the preview. */
60	  [data-piece="I"] { background: #22c5e6 !important; }
61	  [data-piece="O"] { background: #f2d024 !important; }
62	  [data-piece="T"] { background: #a64ee6 !important; }
63	  [data-piece="S"] { background: #3fcf5a !important; }
64	  [data-piece="Z"] { background: #e8423f !important; }
65	  [data-piece="J"] { background: #3563e9 !important; }
66	  [data-piece="L"] { background: #f08a24 !important; }
67	</style>
68	</head>
69	<body>
70	<div class="game">
71	  <div class="board" data-testid="board" id="board"></div>
72	  <div class="side">
73	    <div class="panel"><div class="label">Score</div><div class="value" data-testid="score" id="score">0</div></div>
74	    <div class="panel"><div class="label">Level</div><div class="value" data-testid="level" id="level">1</div></div>
75	    <div class="panel"><div class="label">Lines</div><div class="value" data-testid="lines" id="lines">0</div></div>
76	    <div class="panel"><div class="label">Hold</div><div class="preview hold-item" data-testid="hold-piece" id="hold" data-piece=""></div></div>
77	    <div class="panel"><div class="label">Next</div><div class="next-list" data-testid="next-piece" id="preview"></div></div>
78	    <div class="status" data-testid="game-over" id="status" hidden>Game over</div>
79	    <div class="paused" data-testid="paused-indicator" id="paused" hidden>Paused</div>
80	    <button type="button" data-testid="pause-btn" id="pause">Pause</button>
81	    <button type="button" id="restart">New game</button>
82	    <div class="help">← → move<br>↑ rotate<br>↓ soft drop<br>Space hard drop<br>C / Shift hold<br>P / Esc pause</div>
83	  </div>
84	</div>
85	<script>
86	(function () {
87	  "use strict";
88	
89	  var ROWS = 20;
90	  var COLS = 10;
91	  var TYPES = ["I", "O", "T", "S", "Z", "J", "L"];
92	  var MIN_UPCOMING = 5;
93	  // [REQ-006] Show only the next piece.
94	  var PREVIEW_COUNT = 1;
95	
96	  // Spawn shapes as [row, col] offsets from the top-left of the spawn box.
97	  var SHAPES = {
98	    I: [[0, 0], [0, 1], [0, 2], [0, 3]],
99	    O: [[0, 0], [0, 1], [1, 0], [1, 1]],
100	    T: [[0, 1], [1, 0], [1, 1], [1, 2]],
101	    S: [[0, 1], [0, 2], [1, 0], [1, 1]],
102	    Z: [[0, 0], [0, 1], [1, 1], [1, 2]],
103	    J: [[0, 0], [1, 0], [1, 1], [1, 2]],
104	    L: [[0, 2], [1, 0], [1, 1], [1, 2]]
105	  };
106	  var SPAWN_COL = { I: 3, O: 4, T: 3, S: 3, Z: 3, J: 3, L: 3 };
107	  // Size of the square box each piece rotates inside.
108	  var BOX = { I: 4, O: 2, T: 3, S: 3, Z: 3, J: 3, L: 3 };
109	  // Sideways shifts tried, in order, when a rotated shape does not fit in place.
110	  var KICKS = [0, -1, 1, -2, 2];
111	  // Locking rule (decision): 2 ticks unable to fall, left/right restarts it at most 3 times.
112	  var LOCK_TICKS = 2;
113	  var MAX_LOCK_RESETS = 3;
114	  // Scoring (decision): points by rows cleared at once, times level. Clearing rows together
115	  // must always beat clearing the same rows in smaller groups. Soft drop 1/cell, hard drop 2/cell.
116	  var LINE_SCORES = [0, 100, 300, 500, 800];
117	  var SOFT_DROP_POINTS = 1;
118	  var HARD_DROP_POINTS = 2;
119	
120	  // board[row][col] is a piece letter or null. The renderer and getBoard both read it.
121	  var board;
122	  var current;   // { type, cells, row, col, lockTicks, lockResets } or null
123	  var upcoming;  // array of piece letters, soonest first
124	  var hold;      // held piece letter or null
125	  var holdUsed;  // true once the falling piece has been held; cleared when a piece locks
126	  var score, level, lines, status;  // status: "running", "paused" or "gameover"
127	  var timer = null;
128	  var nextTickAt = 0;       // when the pending gravity step is due (ms timestamp)
129	  var pausedRemaining = 0;  // ms left until the next gravity step when pause began
130	
131	  var boardEl = document.getElementById("board");
132	  var previewEl = document.getElementById("preview");
133	  var holdEl = document.getElementById("hold");
134	  var scoreEl = document.getElementById("score");
135	  var levelEl = document.getElementById("level");
136	  var linesEl = document.getElementById("lines");
137	  var statusEl = document.getElementById("status");
138	  var pausedEl = document.getElementById("paused");
139	  var pauseBtn = document.getElementById("pause");
140	  var cellEls = [];
141	  var previewItems = [];  // { el, minis } per upcoming piece shown, soonest first
142	  var holdMinis = [];
143	
144	  // [REQ-001] Build the 200 board cells and the preview cells once.
145	  // [REQ-004] The preview holds PREVIEW_COUNT items, each a 4x2 grid of mini cells.
146	  // [REQ-006] PREVIEW_COUNT is 1: one item, the next piece.
147	  function buildDom() {
148	    for (var r = 0; r < ROWS; r++) {
149	      cellEls.push([]);
150	      for (var c = 0; c < COLS; c++) {
151	        var el = document.createElement("div");
152	        el.className = "cell";
153	        el.setAttribute("data-testid", "cell");
154	        el.setAttribute("data-row", String(r));
155	        el.setAttribute("data-col", String(c));
156	        el.setAttribute("data-filled", "false");
157	        el.setAttribute("data-piece", "");
158	        el.setAttribute("data-ghost", "false");
159	        boardEl.appendChild(el);
160	        cellEls[r].push(el);
161	      }
162	    }
163	    for (var i = 0; i < PREVIEW_COUNT; i++) {
164	      var item = document.createElement("div");
165	      item.className = "preview next-item";
166	      item.setAttribute("data-testid", "next-piece-item");
167	      item.setAttribute("data-piece", "");
168	      var minis = [];
169	      for (var k = 0; k < 8; k++) {
170	        var m = document.createElement("div");
171	        m.className = "mini";
172	        m.setAttribute("data-piece", "");
173	        item.appendChild(m);
174	        minis.push(m);
175	      }
176	      previewEl.appendChild(item);
177	      previewItems.push({ el: item, minis: minis });
178	    }
179	    // [REQ-007] The hold display: the same 4x2 grid as a preview item.
180	    for (var h = 0; h < 8; h++) {
181	      var hm = document.createElement("div");
182	      hm.className = "mini";
183	      hm.setAttribute("data-piece", "");
184	      holdEl.appendChild(hm);
185	      holdMinis.push(hm);
186	    }
187	  }
188	
189	  function emptyBoard() {
190	    var b = [];
191	    for (var r = 0; r < ROWS; r++) {
192	      var row = [];
193	      for (var c = 0; c < COLS; c++) row.push(null);
194	      b.push(row);
195	    }
196	    return b;
197	  }
198	
199	  function isType(t) { return TYPES.indexOf(t) !== -1; }
200	
201	  // [REQ-001] Random generator: a shuffled bag of all seven pieces.
202	  function randomBag() {
203	    var bag = TYPES.slice();
204	    for (var i = bag.length - 1; i > 0; i--) {
205	      var j = Math.floor(Math.random() * (i + 1));
206	      var t = bag[i]; bag[i] = bag[j]; bag[j] = t;
207	    }
208	    return bag;
209	  }
210	
211	  function fillUpcoming() {
212	    while (upcoming.length < MIN_UPCOMING) upcoming = upcoming.concat(randomBag());
213	  }
214	
215	  function cellsOf(piece, row, col) {
216	    return piece.cells.map(function (o) { return [row + o[0], col + o[1]]; });
217	  }
218	
219	  function fits(piece, row, col) {
220	    var cells = cellsOf(piece, row, col);
221	    for (var i = 0; i < cells.length; i++) {
222	      var r = cells[i][0], c = cells[i][1];
223	      if (r < 0 || r >= ROWS || c < 0 || c >= COLS) return false;
224	      if (board[r][c]) return false;
225	    }
226	    return true;
227	  }
228	
229	  // [REQ-001] Take the next piece from the queue and place it at the top.
230	  function spawn() {
231	    fillUpcoming();
232	    var type = upcoming.shift();
233	    fillUpcoming();
234	    spawnType(type);
235	  }
236	
237	  // [REQ-004] If the new piece does not fit where it spawns, the game is over.
238	  // [REQ-007] Pieces from the queue and from hold both enter here, at the spawn position.
239	  function spawnType(type) {
240	    var piece = {
241	      type: type,
242	      cells: SHAPES[type].map(function (o) { return o.slice(); }),
243	      row: 0,
244	      col: SPAWN_COL[type],
245	      lockTicks: 0,
246	      lockResets: 0
247	    };
248	    if (!fits(piece, piece.row, piece.col)) {
249	      current = null;
250	      status = "gameover";
251	      stopTimer();
252	      return;
253	    }
254	    current = piece;
255	  }
256	
257	  // [REQ-003] Remove full rows, drop the rows above, add rows to lines and score at the current level.
258	  function clearLines() {
259	    var kept = board.filter(function (row) {
260	      return row.some(function (v) { return !v; });
261	    });
262	    var cleared = ROWS - kept.length;
263	    while (kept.length < ROWS) {
264	      var empty = [];
265	      for (var c = 0; c < COLS; c++) empty.push(null);
266	      kept.unshift(empty);
267	    }
268	    board = kept;
269	    if (cleared > 0) {
270	      score += LINE_SCORES[cleared] * level;
271	      lines += cleared;
272	      // [REQ-007] One level per 10 lines crossed, counted from the current level, so setLevel carries on.
273	      var gained = Math.floor(lines / 10) - Math.floor((lines - cleared) / 10);
274	      if (gained > 0) {
275	        level += gained;
276	        if (status === "running") startTimer();
277	      }
278	    }
279	  }
280	
281	  // [REQ-001] Lock the falling piece into the board, clear lines, spawn the next piece.
282	  function lockPiece() {
283	    cellsOf(current, current.row, current.col).forEach(function (rc) {
284	      board[rc[0]][rc[1]] = current.type;
285	    });
286	    current = null;
287	    holdUsed = false;
288	    clearLines();
289	    spawn();
290	  }
291	
292	  // [REQ-007] Hold: put the falling piece aside (or swap with the held one). Once per piece.
293	  function holdPiece() {
294	    if (holdUsed) return;
295	    var type = current.type;
296	    var out = hold;
297	    hold = type;
298	    holdUsed = true;
299	    current = null;
300	    if (out) spawnType(out); else spawn();
301	  }
302	
303	  // [REQ-001] One gravity step. The real timer and __tetris.tick both call this.
304	  // [REQ-002] A step that cannot move the piece down counts one tick of lock delay.
305	  function gravityStep() {
306	    if (status !== "running" || !current) return;
307	    if (fits(current, current.row + 1, current.col)) {
308	      current.row += 1;
309	      current.lockTicks = 0;
310	    } else {
311	      current.lockTicks += 1;
312	      if (current.lockTicks >= LOCK_TICKS) lockPiece();
313	    }
314	  }
315	
316	  // [REQ-002] Restart the lock delay, at most 3 times per piece.
317	  // [REQ-005] Sideways moves and soft drops on a resting piece share this budget.
318	  function resetLock() {
319	    if (current.lockResets < MAX_LOCK_RESETS) {
320	      current.lockResets += 1;
321	      current.lockTicks = 0;
322	    }
323	  }
324	
325	  // [REQ-002] Sideways move. While resting, a move restarts the lock delay.
326	  function shift(dx) {
327	    if (!fits(current, current.row, current.col + dx)) return;
328	    var resting = !fits(current, current.row + 1, current.col);
329	    current.col += dx;
330	    if (resting) resetLock();
331	  }
332	
333	  // [REQ-002] Rotate clockwise inside the piece's box; try sideways shifts; refuse if none fit.
334	  function rotateCW() {
335	    var n = BOX[current.type];
336	    var rotated = { type: current.type, cells: current.cells.map(function (o) { return [o[1], n - 1 - o[0]]; }) };
337	    for (var i = 0; i < KICKS.length; i++) {
338	      if (fits(rotated, current.row, current.col + KICKS[i])) {
339	        current.cells = rotated.cells;
340	        current.col += KICKS[i];
341	        return;
342	      }
343	    }
344	  }
345	
346	  // [REQ-001] Player actions: left, right, softDrop, hardDrop. [REQ-002] rotateCW. [REQ-007] hold.
347	  // [REQ-003] Soft drop scores 1 per cell moved, hard drop 2 per cell dropped.
348	  // [REQ-005] Soft drop on a resting piece scores nothing but restarts the lock delay like a sideways move.
349	  // [REQ-009] "pause" toggles pause; every other action is ignored while paused.
350	  function doInput(action) {
351	    if (action === "pause") { togglePause(); return; }
352	    if (status !== "running" || !current) return;
353	    if (action === "left") {
354	      shift(-1);
355	    } else if (action === "right") {
356	      shift(1);
357	    } else if (action === "rotateCW") {
358	      rotateCW();
359	    } else if (action === "softDrop") {
360	      if (fits(current, current.row + 1, current.col)) {
361	        current.row += 1;
362	        score += SOFT_DROP_POINTS;
363	      } else {
364	        resetLock();
365	      }
366	    } else if (action === "hardDrop") {
367	      while (fits(current, current.row + 1, current.col)) {
368	        current.row += 1;
369	        score += HARD_DROP_POINTS;
370	      }
371	      lockPiece();
372	    } else if (action === "hold") {
373	      holdPiece();
374	    }
375	  }
376	
377	  // [REQ-007] Gravity interval in ms for the current level.
378	  function gravityInterval() {
379	    return Math.max(100, 1000 - (level - 1) * 100);
380	  }
381	
382	  function stopTimer() {
383	    if (timer !== null) { clearTimeout(timer); timer = null; }
384	  }
385	
386	  // One gravity step per timeout, chained. delay overrides the wait before the first step.
387	  function startTimer(delay) {
388	    stopTimer();
389	    var wait = delay === undefined ? gravityInterval() : delay;
390	    nextTickAt = Date.now() + wait;
391	    var id = setTimeout(function () {
392	      if (timer === id) timer = null;
393	      gravityStep();
394	      // gravityStep may already have restarted (level up) or stopped (game over) the timer.
395	      if (status === "running" && timer === null) startTimer();
396	      render();
397	    }, wait);
398	    timer = id;
399	  }
400	
401	  // [REQ-009] Pause freezes gravity and the lock delay exactly where they are. Resuming keeps the
402	  // piece's lock ticks and restarts, and waits only the time that was left before the next step,
403	  // so pausing never buys extra time on a resting piece.
404	  function togglePause() {
405	    if (status === "running") {
406	      status = "paused";
407	      pausedRemaining = Math.max(0, nextTickAt - Date.now());
408	      stopTimer();
409	    } else if (status === "paused") {
410	      status = "running";
411	      startTimer(pausedRemaining);
412	    }
413	  }
414	
415	  // [REQ-009] Cells where the falling piece would land if dropped straight down.
416	  function ghostCells() {
417	    if (!current) return [];
418	    var row = current.row;
419	    while (fits(current, row + 1, current.col)) row += 1;
420	    return cellsOf(current, row, current.col);
421	  }
422	
423	  // [REQ-001] Draw the whole game state into the DOM, synchronously.
424	  // [REQ-009] Ghost cells get data-ghost="true" and stay unfilled; the falling piece draws over them.
425	  function render() {
426	    var drawn = board.map(function (row) { return row.slice(); });
427	    var ghost = {};
428	    ghostCells().forEach(function (rc) { ghost[rc[0] * COLS + rc[1]] = true; });
429	    if (current) {
430	      cellsOf(current, current.row, current.col).forEach(function (rc) {
431	        drawn[rc[0]][rc[1]] = current.type;
432	      });
433	    }
434	    for (var r = 0; r < ROWS; r++) {
435	      for (var c = 0; c < COLS; c++) {
436	        var v = drawn[r][c] || "";
437	        var g = !v && ghost[r * COLS + c] ? "true" : "false";
438	        var el = cellEls[r][c];
439	        if (el.getAttribute("data-piece") !== v) {
440	          el.setAttribute("data-piece", v);
441	          el.setAttribute("data-filled", v ? "true" : "false");
442	        }
443	        if (el.getAttribute("data-ghost") !== g) el.setAttribute("data-ghost", g);
444	      }
445	    }
446	    // [REQ-004] Upcoming pieces in their board colour. [REQ-006] Only the next one is shown.
447	    previewItems.forEach(function (item, i) {
448	      var type = upcoming[i] || "";
449	      item.el.setAttribute("data-piece", type);
450	      item.el.hidden = !type;
451	      item.minis.forEach(function (m) { m.setAttribute("data-piece", ""); });
452	      if (type) {
453	        SHAPES[type].forEach(function (o) {
454	          item.minis[o[0] * 4 + o[1]].setAttribute("data-piece", type);
455	        });
456	      }
457	    });
458	    // [REQ-007] Held piece in its board colour.
459	    holdEl.setAttribute("data-piece", hold || "");
460	    holdMinis.forEach(function (m) { m.setAttribute("data-piece", ""); });
461	    if (hold) {
462	      SHAPES[hold].forEach(function (o) {
463	        holdMinis[o[0] * 4 + o[1]].setAttribute("data-piece", hold);
464	      });
465	    }
466	    scoreEl.textContent = String(score);
467	    levelEl.textContent = String(level);
468	    linesEl.textContent = String(lines);
469	    statusEl.hidden = status !== "gameover";
470	    // [REQ-009] Pause indicator and button label.
471	    pausedEl.hidden = status !== "paused";
472	    pauseBtn.textContent = status === "paused" ? "Resume" : "Pause";
473	    pauseBtn.disabled = status === "gameover";
474	  }
475	
476	  // [REQ-001] Start a fresh game, optionally from a fixed piece queue.
477	  function newGame(queue) {
478	    board = emptyBoard();
479	    score = 0;
480	    level = 1;
481	    lines = 0;
482	    hold = null;
483	    holdUsed = false;
484	    status = "running";
485	    upcoming = Array.isArray(queue) ? queue.filter(isType) : [];
486	    current = null;
487	    spawn();
488	    if (status === "running") startTimer();
489	    render();
490	  }
491	
492	  window.__tetris = {
493	    newGame: function (queue) { newGame(queue); },
494	
495	    setQueue: function (queue) {
496	      upcoming = Array.isArray(queue) ? queue.filter(isType) : [];
497	      fillUpcoming();
498	      render();
499	    },
500	
501	    setBoard: function (rows) {
502	      var b = emptyBoard();
503	      for (var r = 0; r < ROWS; r++) {
504	        var line = (rows && rows[r]) || "";
505	        for (var c = 0; c < COLS; c++) {
506	          var ch = line.charAt(c);
507	          b[r][c] = isType(ch) ? ch : null;
508	        }
509	      }
510	      board = b;
511	      render();
512	    },
513	
514	    tick: function (n) {
515	      if (n === undefined) n = 1;
516	      for (var i = 0; i < n; i++) gravityStep();
517	      if (status === "running") startTimer();
518	      render();
519	    },
520	
521	    // [REQ-007] Set the level for testing. Line levelling continues from here.
522	    setLevel: function (n) {
523	      n = Math.floor(Number(n));
524	      if (!(n >= 1)) return;
525	      level = n;
526	      if (status === "running") startTimer();
527	      render();
528	    },
529	
530	    input: function (action) {
531	      doInput(action);
532	      render();
533	    },
534	
535	    getBoard: function () {
536	      return board.map(function (row) {
537	        return row.map(function (v) { return v || "."; }).join("");
538	      });
539	    },
540	
541	    getState: function () {
542	      return {
543	        current: current
544	          ? { type: current.type, cells: cellsOf(current, current.row, current.col) }
