var KEYS = { ArrowLeft: "left", ArrowRight: "right", ArrowDown: "softDrop", ArrowUp: "rotateCW", " ": "hardDrop", c: "hold", C: "hold", Shift: "hold", p: "pause", P: "pause", Escape: "pause", r: "newGame", R: "newGame" };
// A held key repeats; these actions should fire once per press.
